(async()=>{const origin=location.origin,echo=async(credentials='include',path='/echo')=>(await fetch(origin+path,{credentials}).then(r=>r.json())).cookie||'',out={};await fetch(origin+'/set?name=omitted',{credentials:'omit'});out.omittedSet=await echo();await fetch(origin+'/set?name=normal');out.normalSet=await echo();out.omittedSend=await echo('omit');out.afterOmittedSend=await echo();out.redirectOmit=await echo('omit','/redirect');out.afterRedirect=await echo();return out})()
